n  color: var(--gal-text-muted);\n  font-size: 12px;\n  cursor: pointer;\n  transition:\n    color 0.15s ease,\n    background 0.15s ease;\n\n  &:hover {\n    color: var(--gal-text);\n    background: rgba(255, 255, 255, 0.1);\n  }\n}\n\n.npc-profile__nav-label {\n  font-size: 11px;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n  color: var(--gal-text-muted);\n  opacity: 0.85;\n}\n\n.npc-profile__hero {\n  display: flex;\n  gap: 14px;\n  align-items: flex-start;\n}\n\n.npc-profile__portrait {\n  flex-shrink: 0;\n  padding: 3px;\n  border-radius: 50%;\n  background: var(--gal-gradient-primary);\n  box-shadow: 0 0 20px rgba(244, 114, 182, 0.2);\n}\n\n.npc-profile__avatar-fallback {\n  width: 88px;\n  height: 88px;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 32px;\n  font-weight: 700;\n  color: var(--gal-pink);\n  background: var(--gal-panel-light);\n}\n\n.npc-profile__identity {\n  flex: 1;\n  min-width: 0;\n}\n\n.npc-profile__name {\n  margin: 0 0 10px;\n  font-size: 18px;\n  font-weight: 800;\n  background: var(--gal-gradient-primary);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n  line-height: 1.2;\n  word-break: break-word;\n}\n\n.npc-profile__meta {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.npc-profile__meta-row {\n  display: flex;\n  justify-content: space-between;\n  gap: 8px;\n  font-size: 12px;\n  padding-bottom: 5px;\n  border-bottom: 1px solid var(--gal-border);\n\n  span {\n    color: var(--gal-text-muted);\n    flex-shrink: 0;\n  }\n\n  strong {\n    text-align: right;\n    word-break: break-word;\n  }\n}\n\n.npc-profile__level {\n  color: var(--gal-blue);\n}\n\n.npc-profile__bonds {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 10px;\n}\n\n.bond-card {\n  padding: 12px 12px 10px;\n}\n\n.bond-card__head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-bottom: 8px;\n  font-size: 11px;\n  color: var(--gal-text-muted);\n\n  i {\n    font-size: 13px;\n    color: var(--gal-pink);\n  }\n\n  strong {\n    margin-left: auto;\n    font-size: 18px;\n    font-weight: 800;\n    font-variant-numeric: tabular-nums;\n    color: var(--gal-text);\n  }\n}\n\n.bond-card__bar {\n  height: 5px;\n  border-radius: var(--gal-radius-pill);\n  background: rgba(255, 255, 255, 0.08);\n  overflow: hidden;\n}\n\n.bond-card__fill {\n  height: 100%;\n  border-radius: inherit;\n  transition: width 0.35s ease;\n\n  &--heart {\n    background: linear-gradient(90deg, #fb7185, #f472b6);\n  }\n\n  &--lust {\n    background: linear-gradient(90deg, #f97316, #fb7185);\n  }\n}\n\n.npc-profile__stats {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 10px;\n}\n\n.stat-card {\n  text-align: center;\n  padding: 14px 10px;\n\n  i {\n    display: block;\n    font-size: 18px;\n    margin-bottom: 6px;\n    background: var(--gal-gradient-primary);\n    -webkit-background-clip: text;\n    background-clip: text;\n    color: transparent;\n  }\n}\n\n.stat-card__label {\n  display: block;\n  font-size: 10px;\n  color: var(--gal-text-muted);\n  letter-spacing: 0.06em;\n}\n\n.stat-card__value {\n  font-size: 20px;\n  font-weight: 800;\n  font-variant-numeric: tabular-nums;\n}\n\n.npc-profile__thought {\n  padding: 12px 14px;\n}\n\n.npc-profile__thought-label {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-bottom: 8px;\n  font-size: 10px;\n  letter-spacing: 0.08em;\n  color: var(--gal-violet);\n  font-weight: 700;\n\n  i {\n    font-size: 11px;\n    opacity: 0.9;\n  }\n}\n\n.npc-profile__thought p {\n  margin: 0;\n  font-size: 12px;\n  line-height: 1.6;\n  color: var(--gal-text-muted);\n  font-style: italic;\n}\n"],"sourceRoot":""}]);
